
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mspbel_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mspbel", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.608434738953508e+00, -4.517746593251346e+00, -4.390716583525277e+00, -4.214846201892767e+00, -3.975410577614353e+00, -3.657197995748536e+00, -3.248637475290995e+00, -2.749237151884169e+00, -2.178618977632876e+00, -1.563615452193466e+00, -9.994339533539831e-01, -6.723856846093988e-01, -6.046660191409462e-01, -5.132691323896070e-01, -3.652747828910723e-01, -2.258393767176268e-01, -1.247144719924566e-01, -4.885286740977426e-02, -1.080451538471013e-02, -1.216191333016008e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


